B.aGb=new A.fR("INVALID_CAST_FUNCTION_EXPR","CompileTimeErrorCode.INVALID_CAST_FUNCTION_EXPR","The function expression type '{0}' isn't of type '{1}'. This means its parameter or return type doesn't match what is expected. Consider changing parameter type(s) or the returned type(s).",null)
